<?php use App\Core\Csrf;$v=fn($key)=>$input[$key]??''; ?>
<div class="page-heading"><div><p class="eyebrow">Protection</p><h1>Add insurance policy</h1><p>Register coverage for a student, teacher, or employee.</p></div><a class="button" href="<?=e(url('/insurance'))?>">Cancel</a></div><?php if($errors):?><div class="alert danger"><?=e(implode(' ',$errors))?></div><?php endif;?><form method="post" action="<?=e(url('/insurance'))?>" class="stack-form"><?=Csrf::field()?><section class="card form-section"><h2>Policy holder</h2><div class="grid two"><label>Holder type<select name="holder_type" data-holder-type><option value="student" <?=$v('holder_type')==='student'?'selected':''?>>Student</option><option value="teacher" <?=$v('holder_type')==='teacher'?'selected':''?>>Teacher</option><option value="employee" <?=$v('holder_type')==='employee'?'selected':''?>>Employee</option></select></label><label>Person<select required name="profile_id" data-holder-select><optgroup label="Students" data-type="student"><?php foreach($students as $x):?><option value="<?=$x['id']?>" <?=(string)$v('profile_id')===(string)$x['id']?'selected':''?>><?=e($x['last_name'].', '.$x['first_name'].' — '.$x['student_no'])?></option><?php endforeach;?></optgroup><optgroup label="Teachers" data-type="teacher"><?php foreach($teachers as $x):?><option value="<?=$x['id']?>"><?=e($x['last_name'].', '.$x['first_name'].' — '.$x['employee_no'])?></option><?php endforeach;?></optgroup><optgroup label="Employees" data-type="employee"><?php foreach($employees as $x):?><option value="<?=$x['id']?>"><?=e($x['last_name'].', '.$x['first_name'].' — '.$x['employee_no'])?></option><?php endforeach;?></optgroup></select></label></div><p><small>Need a non-teaching employee? <a href="<?=e(url('/insurance/employees/create'))?>">Create an employee profile first.</a></small></p></section><section class="card form-section"><h2>Coverage information</h2><div class="grid two"><label>Insurance provider<input required name="provider" value="<?=e((string)$v('provider'))?>"></label><label>Policy number<input required name="policy_no" value="<?=e((string)$v('policy_no'))?>"></label><label>Plan name<input name="plan_name" value="<?=e((string)$v('plan_name'))?>"></label><label>Status<select name="status"><?php foreach(['active','pending','expired','cancelled'] as $x):?><option value="<?=$x?>" <?=$v('status')===$x?'selected':''?>><?=e(ucfirst($x))?></option><?php endforeach;?></select></label><label>Coverage starts<input required type="date" name="coverage_start" value="<?=e((string)$v('coverage_start'))?>"></label><label>Coverage ends<input required type="date" name="coverage_end" value="<?=e((string)$v('coverage_end'))?>"></label><label>Premium amount<input type="number" min="0" step="0.01" name="premium_amount" value="<?=e((string)$v('premium_amount'))?>"></label><label>Coverage amount<input type="number" min="0" step="0.01" name="coverage_amount" value="<?=e((string)$v('coverage_amount'))?>"></label></div><label>Remarks<textarea name="remarks" rows="3"><?=e((string)$v('remarks'))?></textarea></label></section><div class="sticky-actions"><button class="button primary">Save insurance policy</button></div></form>
<script>const holderType=document.querySelector('[data-holder-type]'),holderSelect=document.querySelector('[data-holder-select]');function syncHolders(){holderSelect.querySelectorAll('optgroup').forEach(group=>{const active=group.dataset.type===holderType.value;group.hidden=!active;group.querySelectorAll('option').forEach(option=>option.disabled=!active)});const chosen=holderSelect.querySelector('optgroup:not([hidden]) option');if(chosen&&!holderSelect.selectedOptions[0]?.disabled){}else holderSelect.value=chosen?.value||''}holderType?.addEventListener('change',syncHolders);syncHolders();</script>
